 class CompassView extends View{Paint p=new Paint(1);float azimuth=0;CompassView(android.content.Context c){super(c);p.setStrokeWidth(dp(2));}protected void onDraw(Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.40f;p.setStyle(Paint.Style.FILL);p.setColor(Color.WHITE);c.drawCircle(cx,cy,r,p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.rgb(205,168,92));p.setStrokeWidth(dp(2));c.drawCircle(cx,cy,r,p);for(int i=0;i<36;i++){double a=Math.toRadians(i*10-90);float len=i%9==0?dp(11):dp(5);float x1=cx+(float)Math.cos(a)*(r-len),y1=cy+(float)Math.sin(a)*(r-len),x2=cx+(float)Math.cos(a)*r,y2=cy+(float)Math.sin(a)*r;c.drawLine(x1,y1,x2,y2,p);}p.setTextAlign(Paint.Align.CENTER);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(15,76,58));p.setTextSize(dp(16));c.drawText("ش",cx,cy-r+dp(26),p);c.save();c.rotate(q-azimuth,cx,cy);Path arrow=new Path();arrow.moveTo(cx,cy-r*.70f);arrow.lineTo(cx-dp(17),cy-r*.48f);arrow.lineTo(cx+dp(17),cy-r*.48f);arrow.close();p.setColor(Color.rgb(205,168,92));c.drawPath(arrow,p);c.restore();float kw=dp(66),kh=dp(58);p.setColor(Color.BLACK);c.drawRoundRect(cx-kw/2,cy-kh/2,cx+kw/2,cy+kh/2,dp(4),dp(4),p);p.setColor(Color.rgb(205,168,92));c.drawRect(cx-kw/2,cy-kh*.12f,cx+kw/2,cy+kh*.03f,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(Color.rgb(205,168,92));c.drawRoundRect(cx-kw/2,cy-kh/2,cx+kw/2,cy+kh/2,dp(4),dp(4),p);p.setStyle(Paint.Style.FILL);}}
